command:
$ErrorActionPreference="Stop"
$repo=$env:FLYEXPLORER_CANONICAL_CHECKOUT
$main="9051e174da20264f31968e91ddb40289ace10149"
$p1="work/transfer-item-budget-20261006"
$p1sha="2d0d6c84ecfa2fa55239c7713ef709b1f2546360"
$p2="work/outbound-storage-drag-20261006"
$p2sha="eae58315ee638c2917a3f10a822ce612631efc7e"
Set-Location -LiteralPath $repo
& git fetch origin main $p1 $p2 --no-tags --prune
if($LASTEXITCODE -ne 0){throw "cleanup fetch failed"}
$mainSha=(& git rev-parse refs/remotes/origin/main).Trim()
if($mainSha -ne $main){throw "main moved before cleanup: $mainSha"}
$p1Ref="refs/remotes/origin/"+$p1
$p2Ref="refs/remotes/origin/"+$p2
if((& git rev-parse $p1Ref).Trim() -ne $p1sha){throw "P1 branch moved before cleanup"}
if((& git rev-parse $p2Ref).Trim() -ne $p2sha){throw "P2 branch moved before cleanup"}
& git merge-base --is-ancestor $p1sha refs/remotes/origin/main
if($LASTEXITCODE -ne 0){throw "P1 tip is not preserved in main ancestry"}
& git merge-base --is-ancestor $p2sha refs/remotes/origin/main
if($LASTEXITCODE -ne 0){throw "P2 tip is not preserved in main ancestry"}
$mainTree=(& git rev-parse "refs/remotes/origin/main^{tree}").Trim()
$p2Tree=(& git rev-parse ($p2Ref+"^{tree}")).Trim()
if($mainTree -ne $p2Tree){throw "main tree differs from merged P2 tree"}
& git push origin --delete $p2 $p1
if($LASTEXITCODE -ne 0){throw "failed to delete merged P1/P2 branches"}
& git fetch origin --prune --no-tags
if($LASTEXITCODE -ne 0){throw "post-delete fetch failed"}
if(& git show-ref --verify --quiet $p1Ref){throw "P1 remote branch still exists"}
if(& git show-ref --verify --quiet $p2Ref){throw "P2 remote branch still exists"}
Write-Host "P1_P2_MERGED_BRANCH_CLEANUP=PASS"
